 CREATE OR REPLACE FUNCTION public.gettb_servicelist(v_service_id integer, v_lipagesize bigint, v_lipagenumber bigint, sortcolumn character varying, sortorder character varying)                                                                                                                                                                                                                                                                                                                                                                                                      
  RETURNS TABLE(totalcount bigint, service_id integer, service_nm character varying, payment_category_cd character varying, placement_sw character, affiliated_sw character, support_sw character, educational_sw character, structure_service_cd character varying, state_ldss_cd character varying, stateorlocal character varying, placement_structure_id integer, paid_non_paid_cd character, paidnonpaidtype character varying, service_category_cd character, servicecategorydesc character varying, comar_sw character, child_account_sw character, iv_e_allowable_sw character)
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
 DECLARE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
         v_pagenumber int;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
         v_pageoffset int;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
 BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
 IF COALESCE(v_liPageSize, 0) < 1 THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
         v_liPageSize := 10;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
 END IF;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
 IF COALESCE(v_liPageNumber, 0) < 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
 THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
         v_liPageNumber := 1;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
 end if;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
 v_pagenumber := v_liPageNumber - 1;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
 v_pageoffset := v_pagenumber * v_liPageSize;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
 return query                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
 select count(1) over() as totalcount, ts.service_id,ts.service_nm,ts.payment_category_cd,ts.placement_sw,ts.affiliated_sw,ts.support_sw,                                                                                                                                                                                                                                                                                                                                                                                                                                            
 ts.educational_sw,ts.structure_service_cd,ts.state_ldss_cd,(select value_tx from tb_picklist_values where PICKLIST_type_id=956 AND delete_sw='N'                                                                                                                                                                                                                                                                                                                                                                                                                                    
 AND active_sw='Y' AND TRIM(PICKLIST_VALUE_CD)=TRIM(ts.state_ldss_cd)) as stateorlocal,ts.placement_structure_id,ts.paid_non_paid_cd,(select value_tx from tb_picklist_values where PICKLIST_type_id=333 AND delete_sw='N'                                                                                                                                                                                                                                                                                                                                                           
 AND active_sw='Y' AND TRIM(PICKLIST_VALUE_CD)=TRIM(ts.paid_non_paid_cd)) as paidnonpaidtype,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
 ts.service_category_cd,tpv.value_tx as servicecategorydesc, ts.comar_sw,ts.child_account_sw,ts.iv_e_allowable_sw from tb_services ts                                                                                                                                                                                                                                                                                                                                                                                                                                                
 join tb_picklist_values tpv on TRIM(tpv.picklist_value_cd) = TRIM(ts.service_category_cd) and picklist_type_id=1196                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                  where ts.delete_sw='N'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                  and                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                  (v_service_id is null or ts.service_id=v_service_id)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                 order by ( CASE sortorder when 'asc' then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                 CASE sortcolumn                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                 when 'service_nm' then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
           cast( ts.service_nm as character varying)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                 else null end end) asc,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                 ( CASE sortorder when 'desc' then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
                 CASE sortcolumn                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                 when 'service_nm' then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
           cast( ts.service_nm as character varying)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                 else null end end) desc,ts.service_id desc nulls last                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
 LIMIT v_liPageSize OFFSET v_pageoffset;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
 END;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            

